export type MemoryTextKey = DashboardTextMessageKey<typeof memoryMessages>;
export type MemoryPluralKey = DashboardPluralMessageKey<typeof memoryMessages>;

export const MEMORY_CATEGORY_MESSAGE_KEYS: Record<MemoryCategory, MemoryTextKey> = {
  architecture: "categoryArchitecture",
  codebase: "categoryCodebase",
  context: "categoryContext",
  preferences: "categoryPreferences",
  patterns: "categoryPatterns",
  decision: "categoryDecision",
  error: "categoryError",
  learning: "categoryLearning",
};

export const MEMORY_SCOPE_MESSAGE_KEYS: Record<MemoryScope, MemoryTextKey> = {
  sprint: "scopeSprint",
  agent: "scopeAgent",
  project: "scopeProject",
};

export const translateMemory = (
  locale: DashboardLocale,
  key: MemoryTextKey,
  variables?: DashboardMessageVariables,
): string => translateDashboardMessage(memoryMessages, locale, key, variables);

export const translateMemoryPlural = (
  locale: DashboardLocale,
  key: MemoryPluralKey,
  count: number,
  variables?: DashboardMessageVariables,
): string => translateDashboardPlural(memoryMessages, locale, key, count, variables);

export const useMemoryI18n = () => {
  const i18n = useDashboardI18n();
  const t = useCallback((key: MemoryTextKey, variables?: DashboardMessageVariables): string => (
    i18n.translate(memoryMessages, key, variables)
  ), [i18n.translate]);
  const tp = useCallback((key: MemoryPluralKey, count: number, variables?: DashboardMessageVariables): string => (
    i18n.translatePlural(memoryMessages, key, count, variables)
  ), [i18n.translatePlural]);
  return {
    ...i18n,
    t,
    tp,
  };
};
